export class ExpenseListPage {
  private http = inject(HttpClient);
  private toast = inject(ToastService);
  private translate = inject(TranslateService);
  private auth = inject(AuthService);

  private reviewConfirmDialog = viewChild.required<ConfirmDialogComponent>('reviewConfirmDialog');
  private unreviewConfirmDialog = viewChild.required<ConfirmDialogComponent>('unreviewConfirmDialog');

  /** Blade shows the quick-expense button for @can('spend_money') */
  readonly canQuickExpense = this.auth.can('spend_money');

  readonly tableKey = 'list.component';

  readonly columns = [
    { field: 'user', header: 'expense.list.col_user', sortable: true },
    { field: 'type', header: 'expense.list.col_type', sortable: true },
    { field: 'direction', header: 'expense.list.col_direction', sortable: true },
    { field: 'amount', header: 'common.amount', sortable: true },
    { field: 'created_at', header: 'expense.list.col_date', sortable: true },
    { field: 'reviewed', header: 'expense.list.col_review', sortable: true },
    { field: 'attachment', header: 'expense.list.col_attachment', sortable: false },
    { field: 'actions', header: 'common.actions', sortable: false },
  ];

  params = signal<ExpenseListParams>({ page: 1, per_page: 25, q: '', ...DEFAULT_FILTERS });

  data = resource<ListResponse<Row>, unknown>({
    loader: () =>
      firstValueFrom(this.http.get<ListResponse<Row>>('/expenses', { params: cleanParams(this.params()) })),
  });

  /** reference data for the user + direction filters (cacheable endpoint) */
  lookups = resource<Lookups, unknown>({
    loader: () => firstValueFrom(this.http.get<{ data: Lookups }>('/lookups')).then((r) => r.data),
  });

  /** custody options — management list needs manage_treasury; viewers without it just get no options */
  custodies = resource<CustodyRow[], unknown>({
    loader: () =>
      firstValueFrom(this.http.get<ListResponse<CustodyRow>>('/custodies', { params: { per_page: 100 } }))
        .then((r) => r.data)
        .catch(() => [] as CustodyRow[]),
  });

  /** the agent's own spendable custodies for the quick-expense modal */
  userCustodies = resource<UserCustody[], unknown>({
    loader: () =>
      firstValueFrom(this.http.get<ItemResponse<UserCustody[]>>('/user-custodies'))
        .then((r) => r.data)
        .catch(() => [] as UserCustody[]),
  });

  /** type options come from /lookups — the distinct expenses.type values in the database */
  typeOptions = computed(() => [
    { label: ALL, value: 'all' },
    ...(this.lookups.value()?.expense_types ?? []).map((t) => ({ label: this.typeLabel(t), value: t })),
  ]);

  readonly reviewedOptions = [
    { label: ALL, value: 'all' },
    { label: this.translate.instant('enums.review_state.reviewed'), value: 'reviewed' },
    { label: this.translate.instant('enums.review_state.not_reviewed'), value: 'not_reviewed' },
  ];

  userOptions = computed(() => [
    { label: ALL, value: null },
    ...(this.lookups.value()?.users ?? []).map((u) => ({ label: u.name, value: u.id })),
  ]);

  /** flattened direction tree — any node filters itself + its subtree; "none" = expenses without a direction */
  directionOptions = computed(() => {
    const options: { label: string; value: string }[] = [
      { label: ALL, value: 'all' },
      { label: 'بلا توجيه', value: 'none' },
    ];
    const walk = (nodes: DirectionNode[], depth: number): void => {
      for (const node of nodes) {
        options.push({ label: `${'— '.repeat(depth)}${node.name}`, value: `c:${node.id}` });
        walk(node.children, depth + 1);
        for (const item of node.items) {
          options.push({ label: `${'— '.repeat(depth + 1)}${item.name}`, value: `i:${item.id}` });
        }
      }
    };
    walk(this.lookups.value()?.direction_tree ?? [], 0);
    return options;
  });

  custodyOptions = computed(() => [
    { label: ALL, value: null },
    ...(this.custodies.value() ?? []).map((c) => ({ label: custodyLabel(c), value: c.id })),
  ]);

  /** UI-only models for controls whose raw value isn't a query param */
  direction = signal('all');
  amountFrom = signal<number | null>(null);
  amountTo = signal<number | null>(null);
  dateRange = signal<Date[]>([]);
  private amountTimer: ReturnType<typeof setTimeout> | null = null;

  // ── row-action state (T3-22) ────────────────────────────────────────────
  sending = signal(false);
  actionError = signal<HttpErrorResponse | null>(null);
  preview = signal<AttachmentPreview | null>(null);
  reviewTarget = signal<Row | null>(null);
  unreviewTarget = signal<Row | null>(null);
  directionDialogOpen = signal(false);
  directionTarget = signal<Row | null>(null);
  reviewPick = { category_id: null as number | null, item_id: null as number | null, complete: false };
  quickOpen = signal(false);
  quick = {
    custody_id: null as number | null,
    amount: null as number | null,
    description: '',
    line_items: '',
    expense_date: new Date().toISOString().slice(0, 10),
  };

  summaryValue(key: string): string {
    const value = this.data.value()?.meta?.summary?.[key];
    return value === undefined || value === null ? '0' : String(value);
  }

  /** apply any filter change and jump back to the first page */
  setParams(patch: Partial<ExpenseListParams>): void {
    this.params.update((p) => ({ ...p, ...patch, page: 1 }));
    this.data.reload();
  }

  onSearch(term: string): void { this.setParams({ q: term }); }

  /** decode the direction select ('all' | 'none' | 'c:<id>' | 'i:<id>') into query params */
  onDirection(value: string): void {
    this.direction.set(value);
    if (value === 'none') {
      this.setParams({ category_id: null, item_id: null, no_direction: true });
    } else if (value.startsWith('c:')) {
      this.setParams({ category_id: Number(value.slice(2)), item_id: null, no_direction: false });
    } else if (value.startsWith('i:')) {
      this.setParams({ category_id: null, item_id: Number(value.slice(2)), no_direction: false });
    } else {
      this.setParams({ category_id: null, item_id: null, no_direction: false });
    }
  }

  /** apply the picked range once both ends are chosen (or when cleared) */
  onDateRange(value: Date[] | undefined): void {
    const range = value ?? [];
    this.dateRange.set(range);
    if (range.length === 2) {
      this.setParams({ date_from: toIsoDate(range[0]), date_to: toIsoDate(range[1]) });
    } else if (range.length === 0) {
      this.setParams({ date_from: '', date_to: '' });
    }
  }

  /** amount fields fire per keystroke — debounce so one request goes out per pause */
  onAmount(side: 'from' | 'to', value: number | null): void {
    if (side === 'from') {
      this.amountFrom.set(value);
    } else {
      this.amountTo.set(value);
    }
    if (this.amountTimer !== null) {
      clearTimeout(this.amountTimer);
    }
    this.amountTimer = setTimeout(() => {
      this.amountTimer = null;
      this.setParams({ amount_from: this.amountFrom(), amount_to: this.amountTo() });
    }, AMOUNT_DEBOUNCE_MS);
  }

  resetFilters(): void {
    this.direction.set('all');
    this.amountFrom.set(null);
    this.amountTo.set(null);
    this.dateRange.set([]);
    this.setParams({ ...DEFAULT_FILTERS });
  }

  // ── attachment preview ──────────────────────────────────────────────────

  /** the list row only carries has_attachment — fetch the detail for the path/kind */
  openAttachment(row: Row): void {
    void firstValueFrom(this.http.get<ItemResponse<{ attachment: string | null }>>(`/expenses/${row.id}`))
      .then((res) => {
        const path = res.data.attachment ?? '';
        const name = path.split('/').pop() || path;
        this.preview.set({ id: row.id, name, image: /\.(jpe?g|png|gif|webp)$/i.test(path) });
      })
      .catch((err: unknown) => this.toast.apiError((err as HttpErrorResponse).error?.message ?? 'errors.generic', (err as HttpErrorResponse).error?.code));
  }

  attachmentUrl(id: number): string {
    return `/api/v1/expenses/${id}/download-attachment`;
  }

  previewVisibleChange(visible: boolean): void {
    if (!visible) {
      this.preview.set(null);
    }
  }

  // ── quick review / unreview (Blade quickReview / quickUnreview) ────────

  tree(): DirectionNode[] {
    return this.lookups.value()?.direction_tree ?? [];
  }

  startReview(row: Row): void {
    if (row.has_direction) {
      this.reviewTarget.set(row);
      this.reviewConfirmDialog().open();
    } else {
      this.directionTarget.set(row);
      this.reviewPick = { category_id: null, item_id: null, complete: false };
      this.directionDialogOpen.set(true);
    }
  }

  confirmReview(): void {
    const row = this.reviewTarget();
    if (row) {
      this.markReviewed(row);
    }
  }

  onReviewDirection(selection: { category_id: number | null; item_id: number | null; complete: boolean }): void {
    this.reviewPick = selection;
  }

  /**
   * Review of a direction-less expense: when a complete direction is picked
   * (only offered for general-type rows — quick expenses — because the update
   * endpoint requires the full body), it is saved first, then the review is
   * recorded; without a pick this is the plain Blade confirm-and-review.
   */
  submitDirectionReview(): void {
    const row = this.directionTarget();
    if (!row) {
      this.directionDialogOpen.set(false);
      return;
    }
    const pick = this.reviewPick.complete && row.type === 'general' ? this.reviewPick : null;
    this.sending.set(true);
    this.actionError.set(null);
    const update$ = pick
      ? firstValueFrom(
          this.http.post<ActionResponse>(`/expenses/${row.id}/update`, {
            expense_type: 'general',
            amount: row.amount,
            description: row.description ?? '',
            expense_date: (row.expense_date ?? row.created_at ?? '').slice(0, 10),
            expense_category_id: pick.category_id,
            ...(pick.item_id !== null ? { expense_item_id: pick.item_id } : {}),
          }),
        )
      : Promise.resolve(null);
    void update$
      .then(() => { this.markReviewed(row); })
      .catch((err: unknown) => {
        this.sending.set(false);
        this.actionError.set((err as HttpErrorResponse));
      });
  }

  markReviewed(row: Row): void {
    this.sending.set(true);
    void firstValueFrom(this.http.post<ActionResponse>(`/expenses/${row.id}/mark-reviewed`, {}))
      .then((res) => {
        this.sending.set(false);
        this.directionDialogOpen.set(false);
        this.reviewTarget.set(null);
        this.directionTarget.set(null);
        this.toast.success(res.message);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        this.toast.apiError((err as HttpErrorResponse).error?.message ?? 'errors.generic', (err as HttpErrorResponse).error?.code);
      });
  }

  startUnreview(row: Row): void {
    this.unreviewTarget.set(row);
    this.unreviewConfirmDialog().open();
  }

  confirmUnreview(): void {
    const row = this.unreviewTarget();
    if (!row) {
      return;
    }
    this.sending.set(true);
    void firstValueFrom(this.http.post<ActionResponse>(`/expenses/${row.id}/unreview`, {}))
      .then((res) => {
        this.sending.set(false);
        this.unreviewTarget.set(null);
        this.toast.success(res.message);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        this.toast.apiError((err as HttpErrorResponse).error?.message ?? 'errors.generic', (err as HttpErrorResponse).error?.code);
      });
  }

  // ── quick expense (POST /expenses/quick-store) ──────────────────────────

  selectedQuickCustody(): UserCustody | null {
    return (this.userCustodies.value() ?? []).find((c) => c.id === this.quick.custody_id) ?? null;
  }

  submitQuick(): void {
    if (this.quick.custody_id === null || this.quick.amount === null) {
      return;
    }
    this.sending.set(true);
    this.actionError.set(null);
    const body: Record<string, unknown> = {
      custody_id: this.quick.custody_id,
      amount: this.quick.amount,
      description: this.quick.description,
      expense_date: this.quick.expense_date,
      is_quick_expense: true,
    };
    if (this.quick.line_items.trim() !== '') {
      body.line_items = this.quick.line_items;
    }
    void firstValueFrom(this.http.post<ActionResponse>('/expenses/quick-store', body))
      .then((res) => {
        this.sending.set(false);
        this.toast.success(res.message);
        this.quickOpen.set(false);
        this.data.reload();
      })
      .catch((err: unknown) => {
        this.sending.set(false);
        this.actionError.set((err as HttpErrorResponse));
        this.toast.apiError((err as HttpErrorResponse).error?.message ?? 'errors.generic', (err as HttpErrorResponse).error?.code);
      });
  }

  /** localized label for an expense type, falling back to the raw DB value */
  private typeLabel(type: string): string {
    const key = `enums.expense_type.${type}`;
    const label = this.translate.instant(key);
    return label !== key ? label : type;
  }

  onPage(event: { page: number; per_page: number; sort?: string }): void {
    const current = this.params();
    const sort = event.sort ?? '';
    if (current.page === event.page && current.per_page === event.per_page && current.sort === sort) {
      return;
    }
    this.params.update((p) => ({ ...p, page: event.page, per_page: event.per_page, sort: event.sort ?? '' }));
    this.data.reload();
  }
}

function cleanParams(params: object): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(params)) {
    if (value !== null && value !== undefined && value !== '' && value !== 'all' && value !== false) {
      result[key] = String(value);
    }
  }
  return result;
}

/** local calendar day as yyyy-mm-dd — the picker's chosen day is the day sent to the API */
function toIsoDate(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

/** custody options read "reason — agent name" (T31 wording), falling back to the id */
function custodyLabel(c: CustodyRow): string {
  const reason = c.notes !== null && c.notes.trim() !== '' ? c.notes : `عهدة #${c.id}`;
  const agent = c.agent?.name;
  return agent ? `${reason} — ${agent}` : reason;
}
